import os
import pathlib
from typing import Dict, Iterable, Tuple

# Constants are defined at the top level as per the specification.
EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

def is_generated_path(path: str) -> bool:
    """True if the path lives inside a machine-generated directory."""
    if not path:
        return False

    # Use os.path.normpath to normalize path separators and remove redundant ones.
    # Then split by the normalized separator.
    # This is a more 'raw' approach than pathlib.PurePath.parts, which might
    # handle some edge cases differently or be affected by OS-specific behavior
    # in a way that's not immediately obvious.
    normalized_path = os.path.normpath(path)
    # Split by both '/' and '\' to be robust, then filter out empty strings.
    # pathlib.PurePath.parts is generally better, but for debugging,
    # let's try a more explicit string manipulation.
    parts = [p for p in normalized_path.replace('\\', '/').split('/') if p]

    for part in parts:
        # Check for exact segment match
        if part in EXCLUDED_DIR_SEGMENTS:
            return True

        # Check for suffix match
        for suffix in EXCLUDED_DIR_SUFFIXES:
            if part.endswith(suffix):
                return True

    return False

def is_malformed_path(path: str) -> bool:
    """True if markdown formatting, stray whitespace, or invalid punctuation leaked into the filename.

    Agents emit paths through a ReAct text protocol, so bold markers (`*`),
    backticks (`` ` ``), leading/trailing whitespace, trailing dots (`.`) or
    tildes (`~`), or leading hyphens (`-`) periodically survive into `write_file`
    calls. The resulting files are unusable -- `routing.py**` or `notes.` is not
    valid -- so any path containing `*` or `` ` ``, leading/trailing whitespace,
    starting with `-`, or ending with `.` or `~` is malformed.
    """
    if not path:
        # An empty path is implicitly malformed as it's not a valid file path.
        return True

    # Check for markdown or other invalid characters anywhere in the path.
    if '*' in path or '`' in path:
        return True

    # Check for leading/trailing whitespace.
    if path.strip() != path:
        return True

    # Check for leading hyphen.
    if path.startswith('-'):
        return True

    # Check for trailing dot or tilde.
    if path.endswith('.') or path.endswith('~'):
        return True

    return False

def sanitize_path(path: str) -> str:
    """Strips markdown decoration from an agent-supplied path.

    Applied at write time so the artifact lands at its intended location rather
    than being silently created with a broken name.
    """
    sanitized_path = path.strip()
    sanitized_path = sanitized_path.replace('*', '').replace('`', '')

    # Iteratively strip trailing characters to handle cases like 'file.~.'
    while sanitized_path and (sanitized_path.endswith('.') or sanitized_path.endswith('~')):
        sanitized_path = sanitized_path[:-1]

    # Strip leading hyphen only if it exists and the path is not just a hyphen.
    if sanitized_path.startswith('-') and len(sanitized_path) > 1:
        sanitized_path = sanitized_path[1:]
    elif sanitized_path == '-': # Handle case where path is just '-'
        sanitized_path = ''

    return sanitized_path

def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
    """Returns only genuinely agent-authored files from a path->content map."""
    return {
        path: content
        for path, content in bundle.items()
        if not is_malformed_path(path) and not is_generated_path(path)
    }

def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
    """Splits a bundle into (authored, generated, malformed) for reporting."""
    authored: Dict[str, str] = {}
    generated: Dict[str, str] = {}
    malformed: Dict[str, str] = {}

    for path, content in bundle.items():
        if is_malformed_path(path):
            malformed[path] = content
        elif is_generated_path(path):
            generated[path] = content
        else:
            authored[path] = content

    return authored, generated, malformed

def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str]=('.py',)) -> int:
    """Counts authored files matching the given suffixes."""
    authored_bundle = filter_bundle(bundle)

    # Ensure suffixes is a tuple for the endswith() method.
    # If suffixes is empty, no files will match.
    if not suffixes:
        return 0
    suffix_tuple = tuple(suffixes)

    count = sum(1 for path in authored_bundle if path.endswith(suffix_tuple))
    return count
